import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

// --- Components ---

const FlowBox: React.FC<{
  text: string;
  color: string;
  x: number;
  y: number;
  width: number;
  height: number;
  delay: number;
  fontFamily: string;
}> = ({ text, color, x, y, width: w, height: h, delay, fontFamily }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const entrance = spring({
    frame: frame - delay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const opacity = interpolate(frame - delay, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        left: x - w / 2,
        top: y - h / 2,
        width: w,
        height: h,
        backgroundColor: color,
        borderRadius: h / 2, // Fully rounded sides
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        color: "white",
        fontFamily,
        fontSize: h * 0.25,
        fontWeight: 600,
        boxShadow: "0 10px 20px rgba(0,0,0,0.1)",
        transform: `scale(${entrance})`,
        opacity,
        zIndex: 2,
      }}
    >
      {text}
    </div>
  );
};

const FlowConnector: React.FC<{
  startX: number;
  startY: number;
  endX: number;
  endY: number;
  direction: "left-to-right" | "right-to-left";
  delay: number;
  color: string;
}> = ({ startX, startY, endX, endY, direction, delay, color }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Draw logic
  const progress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 20, stiffness: 80 },
  });

  // Calculate path
  // If left-to-right: Start is Right edge of Box 1, End is Right edge of Box 2
  // If right-to-left: Start is Left edge of Box 2, End is Left edge of Box 3

  const cornerRadius = 40;
  const loopOut = 80; // How far out the line goes

  let d = "";
  if (direction === "left-to-right") {
    // Exits right, enters from right
    // M startX startY -> H (startX + loopOut) -> V (endY) -> H endX
    const turnX = Math.max(startX, endX) + loopOut;
    
    d = `
      M ${startX} ${startY}
      L ${turnX - cornerRadius} ${startY}
      Q ${turnX} ${startY} ${turnX} ${startY + cornerRadius}
      L ${turnX} ${endY - cornerRadius}
      Q ${turnX} ${endY} ${turnX - cornerRadius} ${endY}
      L ${endX} ${endY}
    `;
  } else {
    // Exits left, enters from left
    const turnX = Math.min(startX, endX) - loopOut;
    
    d = `
      M ${startX} ${startY}
      L ${turnX + cornerRadius} ${startY}
      Q ${turnX} ${startY} ${turnX} ${startY + cornerRadius}
      L ${turnX} ${endY - cornerRadius}
      Q ${turnX} ${endY} ${turnX + cornerRadius} ${endY}
      L ${endX} ${endY}
    `;
  }

  // Arrowhead logic
  // We need to know the angle at the end. 
  // For left-to-right, we approach endX from the right, so angle is 180 deg (pointing left).
  // For right-to-left, we approach endX from the left, so angle is 0 deg (pointing right).
  
  const arrowAngle = direction === "left-to-right" ? 180 : 0;
  const arrowSize = 10;
  
  // Create arrow path
  const arrowPath = `M 0 0 L -${arrowSize} -${arrowSize/2} L -${arrowSize} ${arrowSize/2} Z`;

  return (
    <svg
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        overflow: "visible",
        zIndex: 1,
        pointerEvents: "none"
      }}
    >
      <path
        d={d}
        stroke={color}
        strokeWidth={3}
        fill="none"
        strokeLinecap="round"
        style={{
          strokeDasharray: 2000,
          strokeDashoffset: 2000 * (1 - progress),
        }}
      />
      {/* Arrowhead marker at the end of the path */}
       <g 
        transform={`translate(${endX}, ${endY}) rotate(${arrowAngle}) scale(${Math.min(1, progress * 5)})`}
        opacity={progress > 0.1 ? 1 : 0}
       >
          <path d={arrowPath} fill={color} />
       </g>
    </svg>
  );
};

// --- Main Schema & Component ---



export type FlowChartAnimationProps = Record<string, any>;

const FlowChartAnimation: React.FC<FlowChartAnimationProps> = ({
  backgroundColor = "#f0f4f1",
  transparentBackground = false,
  steps = [
    "Identify Market Need",
    "Create Business Plan",
    "Launch Product",
    "Promote Business",
  ],
  stepPrimaryColor = "#6b95d6",
  stepSecondaryColor = "#62b587",
  connectorColor = "#000000",
  durationInSeconds = 10,
}) => {
  useFontLoader(["Inter", "Roboto"]);
  
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout Calculations
  const boxWidth = width * 0.25;
  const boxHeight = height * 0.12;
  const startY = height * 0.25;
  const gapY = height * 0.18;
  const centerOffset = width * 0.12; // Offset from center line

  // Determine positions
  const items = useMemo(() => {
    return steps.map((text, i) => {
      const isLeft = i % 2 === 0;
      return {
        id: i,
        text,
        x: width / 2 + (isLeft ? -centerOffset : centerOffset),
        y: startY + i * gapY,
        color: i === steps.length - 1 ? stepSecondaryColor : stepPrimaryColor, // Last one is green in ref
        direction: isLeft ? "left" : "right",
      };
    });
  }, [steps, width, height, startY, gapY, centerOffset, stepPrimaryColor, stepSecondaryColor]);

  // Timing
  const stepInterval = 25; // frames between step reveals
  const pathDuration = 20; // frames for path to draw
  
  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
      }}
    >
      {/* Render Connectors First (so they are behind boxes) */}
      {items.map((item, i) => {
        if (i === items.length - 1) return null;
        
        const nextItem = items[i + 1];
        const delay = 30 + i * (stepInterval + pathDuration); // Start after box i is revealed

        // Determine connector points
        // If current is Left, next is Right.
        // Current(Left) -> Next(Right)
        // Path logic: Exit Right Edge of Left, Enter Right Edge of Right
        
        let startX, endX, direction: "left-to-right" | "right-to-left";

        if (item.direction === "left") { // Should go to right box
           // Left box: x is center-offset. Right edge is x + w/2
           startX = item.x + boxWidth / 2;
           // Right box: x is center+offset. Right edge is x + w/2
           endX = nextItem.x + boxWidth / 2;
           direction = "left-to-right";
        } else {
           // Right box: x is center+offset. Left edge is x - w/2
           startX = item.x - boxWidth / 2;
           // Left box: x is center-offset. Left edge is x - w/2
           endX = nextItem.x - boxWidth / 2;
           direction = "right-to-left";
        }

        return (
          <FlowConnector
            key={`conn-${i}`}
            startX={startX}
            startY={item.y}
            endX={endX}
            endY={nextItem.y}
            direction={direction}
            delay={delay}
            color={connectorColor}
          />
        );
      })}

      {/* Render Boxes */}
      {items.map((item, i) => {
        // Timeline:
        // Title was removed so we can start earlier or keep same timing.
        // Keeping similar timing for stability:
        
        // Box 0: Frame 20
        // Path 0 (Box0->Box1): Frame 20 + 20 (wait a bit) = 40
        // Box 1: Frame 40 + PathDuration(20) = 60
        
        const boxDelay = 20 + i * (pathDuration + 15);

        return (
          <FlowBox
            key={`box-${i}`}
            text={item.text}
            color={item.color}
            x={item.x}
            y={item.y}
            width={boxWidth}
            height={boxHeight}
            delay={boxDelay}
            fontFamily="Inter, sans-serif"
          />
        );
      })}
    </AbsoluteFill>
  );
};

export default FlowChartAnimation;